module Controller_Gates_1Hot(  output 		Ready,   output 		Load_regs, Incr_R2, Shift_left,   input 		Start, Zero, E, clock, reset_b);  wire w1, w2, w3, w4, w5, w6;  wire T0, T1, T2, T3;  wire set;  assign Ready = T0;  assign Incr_R2 = T1;  assign Shift_left = T2;  and (Load_regs, T0, Start);  not (set, reset_b);  DFF_S M0 (T0, D0, clock, set);		// Note: reset action must initialize S_idle = 4'b0001  DFF M1 (T1, D1, clock, reset_b);  DFF M2 (T2, D2, clock, reset_b);  DFF M3 (T3, D3, clock, reset_b);  not (Start_b, Start);  and (w1, T0, Start_b);  and (w2, T1, Zero);  or (D0, w1, w2);  
  and (w3, T0, Start);  and (w4, T3, E);  or (D1, w3, w4);  not (Zero_b, Zero);  not (E_b, E);  and (w5, T1, Zero_b);  and (w6, T3, E_b);  or (D2, w5, w6);    buf (D3, T2);endmodulemodule DFF (output reg Q, input D, clock, reset_b);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) Q <= 0;    else Q <= D;endmodulemodule DFF_S (output reg Q, input D, clock, set);  always @ (posedge clock, posedge set)    if (set == 1) Q <= 1;	else Q <= D;endmodule